-- Only temporary rows inside a rolled-back transaction. No notice/activity/session
-- INSERT, HTTP requests or real notifications are generated by this test.
BEGIN;
DO $$
DECLARE gm uuid; player uuid; own_team uuid; other_team uuid:=gen_random_uuid(); gs uuid:=gen_random_uuid(); ps uuid:=gen_random_uuid(); e uuid:=gen_random_uuid(); due uuid:=gen_random_uuid(); later uuid:=gen_random_uuid(); cancelled_session uuid:=gen_random_uuid();
BEGIN
 SELECT u.id INTO gm FROM public.users u JOIN auth.users a ON a.id=u.id WHERE lower(btrim(u.role))='admin' LIMIT 1;
 SELECT m.user_id,c.team_id INTO player,own_team FROM public.player_team_members m JOIN auth.users a ON a.id=m.user_id JOIN public.users c ON c.username=m.login_username JOIN public.teams t ON t.id=c.team_id
 WHERE NOT EXISTS(SELECT 1 FROM public.users other_user WHERE other_user.username=m.login_username AND other_user.team_id IS DISTINCT FROM c.team_id)
 AND NOT EXISTS(SELECT 1 FROM public.users u WHERE u.id=m.user_id AND lower(btrim(u.role))='admin') LIMIT 1;
 IF gm IS NULL OR player IS NULL THEN RAISE EXCEPTION 'GM and player test prerequisites missing'; END IF;
 INSERT INTO public.push_subscriptions(id,user_id,endpoint,p256dh,auth,receive_notices,receive_activity,receive_session_reminders,all_teams)
 VALUES(gs,gm,'https://fcm.googleapis.com/transaction-test/'||gs,repeat('A',87),repeat('A',22),true,true,true,true),
       (ps,player,'https://fcm.googleapis.com/transaction-test/'||ps,repeat('A',87),repeat('A',22),true,true,true,true);
 IF NOT EXISTS(SELECT 1 FROM public.campaign_push_recipients('activity',NULL,NULL) WHERE id=gs)
 OR EXISTS(SELECT 1 FROM public.campaign_push_recipients('activity',NULL,NULL) WHERE id=ps) THEN RAISE EXCEPTION 'Master-only recipient check failed'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.campaign_push_recipients('session',own_team,NULL) WHERE id=ps) THEN RAISE EXCEPTION 'Own-team session missing; team_null=%, member=%, subscriptions=%',own_team IS NULL,EXISTS(SELECT 1 FROM public.player_team_members WHERE user_id=player AND team_id=own_team),(SELECT count(*) FROM public.push_subscriptions); END IF;
 IF EXISTS(SELECT 1 FROM public.campaign_push_recipients('session',other_team,NULL) WHERE id=ps) THEN RAISE EXCEPTION 'Other-team session leaked'; END IF;
 UPDATE public.push_subscriptions SET all_teams=false,team_ids='{}' WHERE id=ps;
 IF EXISTS(SELECT 1 FROM public.campaign_push_recipients('session',own_team,NULL) WHERE id=ps) THEN RAISE EXCEPTION 'Session team opt-out failed'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.campaign_push_recipients('notice',NULL,NULL) WHERE id=ps) THEN RAISE EXCEPTION 'Notice independence failed'; END IF;
 INSERT INTO public.campaign_push_events(id,kind,source_id,expires_at) VALUES(e,'activity','transaction-test-'||e,now()+interval '1 minute');
 IF NOT public.claim_campaign_event(e) OR public.claim_campaign_event(e) THEN RAISE EXCEPTION 'Event concurrency lock failed'; END IF;
 IF NOT public.claim_campaign_push(e,gs) OR public.claim_campaign_push(e,gs) THEN RAISE EXCEPTION 'Delivery concurrency lock failed'; END IF;
 UPDATE public.campaign_push_deliveries SET sent_at=now(),claimed_at=now()-interval '4 minutes' WHERE event_id=e;
 IF public.claim_campaign_push(e,gs) THEN RAISE EXCEPTION 'Successful delivery duplicated'; END IF;
 INSERT INTO public.team_sessions(id,team_id,title,starts_at,cancelled) VALUES
 (due,own_team,'transaction due test',now()+interval '10 minutes',false),
 (later,own_team,'transaction later test',now()+interval '11 minutes',false),
 (cancelled_session,own_team,'transaction cancelled test',now()+interval '9 minutes',true);
 PERFORM public.tick_campaign_push();
 PERFORM public.tick_campaign_push();
 BEGIN
  UPDATE public.team_sessions SET team_id=other_team WHERE id=due;
  RAISE EXCEPTION 'Unexpected team move allowed';
 EXCEPTION WHEN raise_exception THEN
  IF SQLERRM <> 'A session cannot be moved to another team; create a separate session' THEN RAISE; END IF;
 END;
 IF (SELECT team_id FROM public.team_sessions WHERE id=due) IS DISTINCT FROM own_team
 OR has_column_privilege('authenticated','public.team_sessions','team_id','UPDATE') THEN RAISE EXCEPTION 'Session team isolation failed'; END IF;
 IF (SELECT count(*) FROM public.campaign_push_events WHERE kind='session' AND source_id=due::text)<>1
 OR EXISTS(SELECT 1 FROM public.campaign_push_events WHERE kind='session' AND source_id IN(later::text,cancelled_session::text)) THEN RAISE EXCEPTION '10-minute scheduling/cancellation/deduplication failed'; END IF;
END; $$;
ROLLBACK;
SELECT 'GM-only activity, session authorization/selection, independent notices, event/delivery leases: passed; all test rows rolled back' AS checks;
